// Some portions generated by Claude
// @ts-check
const { test, expect } = require('@playwright/test');
const {
    createSeededRepository,
    deleteRepository,
    repositoryPageUrl,
    serverBaseUrl,
    uniqueRepositoryId,
    waitForRoute
} = require('./workbench-test-helpers.js');

// The Graph page: reachable from the sidebar, draws the repository's data through the Workbench's own Graph servlet,
// survives leaving and returning, and hands a query over to the Query page.
const REPOSITORY_ID = uniqueRepositoryId('graph-page');

test.beforeAll(async ({ request }) => {
    await createSeededRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

test.afterAll(async ({ request }) => {
    await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

test('the sidebar opens an empty Graph page; Load 100 statements draws nodes', async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'summary'));
    await waitForRoute(page, 'summary');

    await page.locator('#navigation a[href$="graph"]').first().click();
    await waitForRoute(page, 'graph');
    await expect(page).toHaveTitle(`Graph · ${REPOSITORY_ID} — RDF4J Workbench`);
    await expect(page.locator('.graph-explorer')).toHaveCount(1);
    await expect(page.locator('.graph-explorer .empty-state h3')).toHaveText('The graph is empty');
    await expect(page.locator('.graph-explorer .graph-node')).toHaveCount(0);
    await page.locator('.graph-explorer').getByRole('button', { name: 'Load 100 statements' }).click();
    await expect(page.locator('.graph-explorer .graph-node').first()).toBeAttached({ timeout: 30000 });
    expect(await page.locator('.graph-explorer .graph-node').count()).toBeGreaterThan(1);
});

test('the toolbar help lists the gestures and keys; Escape closes it and nothing else', async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'graph'));
    await waitForRoute(page, 'graph');
    const explorer = page.locator('.graph-explorer');
    const help = explorer.getByRole('button', { name: 'How to use the graph' });
    await help.click();
    await expect(help).toHaveAttribute('aria-expanded', 'true');
    const guide = explorer.getByRole('note').filter({ hasText: 'Double-click a node' });
    await expect(guide).toBeVisible();
    await expect(guide).toContainText('never change the repository');
    await page.keyboard.press('Escape');
    await expect(guide).toBeHidden();
    await expect(help).toBeFocused();
    await expect(help).toHaveAttribute('aria-expanded', 'false');
});

test('leaving and returning mounts exactly one explorer, keeps the graph and the Workbench shell intact', async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'graph'));
    await waitForRoute(page, 'graph');
    await page.locator('.graph-explorer').getByRole('button', { name: 'Load 100 statements' }).click();
    await expect(page.locator('.graph-explorer .graph-node').first()).toBeAttached({ timeout: 30000 });

    await page.locator('#navigation a[href$="explore"]').first().click();
    await waitForRoute(page, 'explore');
    await expect(page.locator('.graph-explorer')).toHaveCount(0);
    await expect(page.locator('#workbench-page-surface')).not.toHaveClass(/workbench-page-surface--full-bleed/);

    await page.locator('#navigation a[href$="graph"]').first().click();
    await waitForRoute(page, 'graph');
    await expect(page.locator('.graph-explorer')).toHaveCount(1);
    await expect(page.locator('.graph-explorer .graph-node').first()).toBeAttached({ timeout: 30000 });
    await expect(page.locator('.graph-explorer .empty-state')).toHaveCount(0);
});

test('the query editor hands the SPARQL over to the Query page', async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'graph'));
    await waitForRoute(page, 'graph');
    await page.locator('.graph-explorer').getByRole('button', { name: 'Load 100 statements' }).click();
    await expect(page.locator('.graph-explorer .graph-node').first()).toBeAttached({ timeout: 30000 });

    await page.getByRole('button', { name: 'Query editor' }).click();
    const link = page.locator('.graph-explorer .endpoint-caption a', { hasText: 'Open on the Query page' });
    await expect(link).toHaveAttribute('href', /\/query\?query=SELECT/);
    await link.click();
    await waitForRoute(page, 'query');
    await expect(page).toHaveURL(/\/repositories\/[^/]+\/query\?query=/);
});
